return {["scripts/actions/spells/blue/dream_flower.lua"]={["Path"]="scripts/actions/spells/blue/dream_flower.lua",["SHA256"]="40264711cae0a0f0bfb636973ca56e977c6b19cb8f6a51bf716fbf2ffae0f5a7",["Text"]="-----------------------------------\n-- Spell: Dream Flower\n-- Puts all enemies within range to sleep\n-- Spell cost: 68 MP\n-- Monster Type: Plantoid\n-- Spell Type: Magical (Dark)\n-- Blue Magic Points: 3\n-- Stat Bonus: HP+5 MP+5 CHR+2\n-- Level: 87\n-- Casting Time: Casting Time: 2.5 seconds\n-- Recast Time: Recast Time: 45 seconds\n-- Duration: 90~120 seconds\n-- Magic Bursts on: None\n-- Combos: Magic Attack Bonus\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params           = {}\n    params.ecosystem       = xi.ecosystem.PLANTOID\n    params.effect          = xi.effect.SLEEP_I -- https://wiki.ffo.jp/html/5502.html\n    params.power           = 1\n    params.tick            = 0\n    params.duration        = 90 -- https://wiki.ffo.jp/html/5502.html says the duration might be reduced based on number of targets. Might need to be fixed in the future\n    params.resistThreshold = 0.50\n    params.isGaze          = false\n    params.isConal         = false\n\n    return xi.spells.blue.useEnfeeblingSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/empty_thrash.lua"]={["Path"]="scripts/actions/spells/blue/empty_thrash.lua",["SHA256"]="f856b9e1a598c4cdb15776f080f581984a72dbaebfae60bd3ff36f8630322166",["Text"]="-----------------------------------\n-- Spell: Empty Thrash\n-- Delivers an area attack. Accuracy varies with TP\n-- Spell cost: 33 MP\n-- Monster Type: Empty\n-- Spell Type: Physical (Slashing)\n-- Blue Magic Points: 3\n-- Stat Bonus: STR+3 CHR-2\n-- Level: 87\n-- Casting Time: 0.5 seconds\n-- Recast Time: 40.75 seconds\n-- Skillchain Element(s): Compression, Scission\n-- Combos: Doule Attack, Triple Attack\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params           = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem       = xi.ecosystem.EMPTY\n    params.tpModifier      = xi.spells.blue.tpMod.ACC\n    params.attackType      = xi.attackType.PHYSICAL\n    params.damageType      = xi.damageType.SLASHING\n    params.skillchainType  = xi.skillchainType.COMPRESSION\n    params.skillchainType2 = xi.skillchainType.SCISSION\n    params.shadowBehavior  = xi.mobskills.shadowBehavior.NUMSHADOWS_3 -- guessed\n\n    params.numHits       = 1\n    params.ftp0          = 2.0\n    params.ftp1500       = 2.0\n    params.ftp3000       = 2.0\n    params.ftpAzure      = 2.0\n    params.baseDamageCap = 33\n\n    params.str_wsc = 0.5\n\n    return xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/enervation.lua"]={["Path"]="scripts/actions/spells/blue/enervation.lua",["SHA256"]="61ef28d98735a1ab5023409efee2fb451c292d318a255b270921cc9d86f27bbc",["Text"]="-----------------------------------\n-- Spell: Enervation\n-- Lowers the defense and magical defense of enemies within range\n-- Spell cost: 48 MP\n-- Monster Type: Beastmen\n-- Spell Type: Magical (Dark)\n-- Blue Magic Points: 5\n-- Stat Bonus: HP-5, MP+5\n-- Level: 67\n-- Casting Time: 6 seconds\n-- Recast Time: 60 seconds\n-- Magic Bursts on: Compression, Gravitation, and Darkness\n-- Combos: Counter\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local duration        = 30\n    local resistThreshold = 0.5\n    local returnEffect    = xi.effect.DEFENSE_DOWN\n\n    local params =\n    {\n        effectId       = xi.effect.DEFENSE_DOWN,\n        magicalElement = spell:getElement(),\n        actorStat      = xi.mod.INT,\n        skillType      = xi.skill.BLUE_MAGIC,\n        spellGroup     = spell:getSpellGroup(),\n    }\n\n    local resist = xi.combat.magicHitRate.calculateResistRate(caster, target, params)\n\n    if resist >= resistThreshold then\n\n        local actionOne = target:addStatusEffect(xi.effect.DEFENSE_DOWN, { power = 10, duration = duration * resist, origin = caster })\n        local actionTwo = target:addStatusEffect(xi.effect.MAGIC_DEF_DOWN, { power = 8, duration = duration * resist, origin = caster })\n\n        -- If at least one of effects got applied, set the message type\n        if actionOne or actionTwo then\n            spell:setMsg(xi.msg.basic.MAGIC_ENFEEB_IS)\n        end\n\n        -- Set the returnEffect to effectTwo if the first one failed\n        if not actionOne and actionTwo then\n            returnEffect = xi.effect.MAGIC_DEF_DOWN\n        end\n\n    else\n        spell:setMsg(xi.msg.basic.MAGIC_RESIST)\n    end\n\n    return returnEffect\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/exuviation.lua"]={["Path"]="scripts/actions/spells/blue/exuviation.lua",["SHA256"]="947099cb416dc263a4281f3ff9f9567ed2c14512d5cccb90982ea8cefd9c93d1",["Text"]="-----------------------------------\n-- Spell: Exuviation\n-- Restores HP and removes one detrimental magic effect\n-- Spell cost: 40 MP\n-- Monster Type: Vermin\n-- Spell Type: Magical (Fire)\n-- Blue Magic Points: 4\n-- Stat Bonus: HP+5 MP+5 CHR+1\n-- Level: 75\n-- Casting Time: 3 seconds\n-- Recast Time: 60 seconds\n-----------------------------------\n-- Combos: Resist Sleep\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params           = {}\n    params.minCure         = 60\n    params.divisor0        = 0.6666\n    params.constant0       = -45\n    params.powerThreshold1 = 219\n    params.divisor1        = 2\n    params.constant1       = 65\n    params.powerThreshold2 = 459\n    params.divisor2        = 6.5\n    params.constant2       = 144.6666\n\n    target:eraseStatusEffect()\n    return xi.spells.blue.useCuringSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/eyes_on_me.lua"]={["Path"]="scripts/actions/spells/blue/eyes_on_me.lua",["SHA256"]="294569e1cf4b8801db33fce1cc7cdd6080f4eaca79287e6c89300fa2479c72dc",["Text"]="-----------------------------------\n-- Spell: Eyes On Me\n-- Deals dark damage to an enemy\n-- Spell cost: 112 MP\n-- Monster Type: Demons\n-- Spell Type: Magical (Dark)\n-- Blue Magic Points: 4\n-- Stat Bonus: HP-5, MP+15\n-- Level: 61\n-- Casting Time: 4.5 seconds\n-- Recast Time: 29.25 seconds\n-- Magic Bursts on: Compression, Gravitation, Darkness\n-- Combos: Magic Attack Bonus\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params       = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem   = xi.ecosystem.DEMON\n    params.attackType  = xi.attackType.MAGICAL\n    params.damageType  = xi.damageType.DARK\n    params.dStat       = xi.mod.CHR\n\n    params.ftp0            = 2.625\n    params.azureBonus      = 2\n    params.dStatMultiplier = 1.5\n    params.baseDamageCap    = 69\n\n    params.chr_wsc = 0.4\n\n    return xi.spells.blue.useMagicalSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/feather_barrier.lua"]={["Path"]="scripts/actions/spells/blue/feather_barrier.lua",["SHA256"]="af4812f2758e96172333c2d739c27d83d0d565fd089aec5b39e328bcb50f1110",["Text"]="-----------------------------------\n-- Spell: Feather Barrier\n-- Enhances evasion\n-- Spell cost: 29 MP\n-- Monster Type: Birds\n-- Spell Type: Magical (Wind)\n-- Blue Magic Points: 2\n-- Stat Bonus: None\n-- Level: 56\n-- Casting Time: 2 seconds\n-- Recast Time: 120 seconds\n-- Duration: 30 Seconds\n-----------------------------------\n-- Combos: Resist Gravity\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local power    = 20\n    local duration = xi.spells.blue.calculateDurationWithDiffusion(caster, 30)\n\n    if not target:addStatusEffect(xi.effect.EVASION_BOOST, { power = power, duration = duration, origin = caster }) then\n        spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n    end\n\n    return xi.effect.EVASION_BOOST\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/feather_storm.lua"]={["Path"]="scripts/actions/spells/blue/feather_storm.lua",["SHA256"]="a7b4d40a5c1ec8d960bc336f21a0df4d6bbe6b066b68608ecbb11dba9629f30c",["Text"]="-----------------------------------\n-- Spell: Feather Storm\n-- Additional effect: Poison. Chance of effect varies with TP\n-- Spell cost: 12 MP\n-- Monster Type: Beastmen\n-- Spell Type: Physical (Piercing)\n-- Blue Magic Points: 3\n-- Stat Bonus: CHR+2, HP+5\n-- Level: 12\n-- Casting Time: 0.5 seconds\n-- Recast Time: 10 seconds\n-- Skillchain Element(s): Transfixion\n-- Combos: Rapid Shot\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params          = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem      = xi.ecosystem.BEASTMEN\n    params.tpModifier     = xi.spells.blue.tpMod.DURATION\n    params.attackType     = xi.attackType.RANGED\n    params.damageType     = xi.damageType.PIERCING\n    params.skillchainType = xi.skillchainType.TRANSFIXION\n\n    params.numHits       = 1\n    params.ftp0          = 2\n    params.ftp1500       = 2\n    params.ftp3000       = 2\n    params.ftpAzure      = 2\n    params.baseDamageCap = 17\n\n    params.agi_wsc    = 0.3\n\n    -- Handle damage.\n    local damage = xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\n\n    if params.hitsLanded <= 0 then\n        return damage\n    end\n\n    local duration = 180\n\n    -- TODO: duration needs verification.\n    if params.hasAzureLore then\n        duration = 450\n    elseif params.hasChainAffinity then\n        duration = xi.spells.blue.calculatefTP(caster:getTP(), 180, 360, 400)\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.POISON, 1, 3, duration },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/feather_tickle.lua"]={["Path"]="scripts/actions/spells/blue/feather_tickle.lua",["SHA256"]="a073942df94ccf819e140229fa3e7ad43ed365ff3de35210a560e164b45fb947",["Text"]="-----------------------------------\n-- Spell: Feather Tickle\n-- Reduces an enemy's TP\n-- Spell cost: 48 MP\n-- Monster Type: Birds\n-- Spell Type: Magical (Wind)\n-- Blue Magic Points: 3\n-- Stat Bonus: AGI+1\n-- Level: 64\n-- Casting Time: 4 seconds\n-- Recast Time: 26 seconds\n-- Magic Bursts on: Detonation, Fragmentation, and Light\n-- Combos: Clear Mind\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local power           = 1500\n    local resistThreshold = 0.5\n\n    local params =\n    {\n        magicalElement = spell:getElement(),\n        actorStat      = xi.mod.INT,\n        skillType      = xi.skill.BLUE_MAGIC,\n        spellGroup     = spell:getSpellGroup(),\n    }\n\n    local resist = xi.combat.magicHitRate.calculateResistRate(caster, target, params)\n\n    if resist >= resistThreshold then\n        if target:getTP() == 0 then\n            spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n        else\n            target:delTP(power * resist)\n            spell:setMsg(xi.msg.basic.MAGIC_TP_REDUCE)\n        end\n    else\n        spell:setMsg(xi.msg.basic.MAGIC_RESIST)\n    end\n\n    return 0\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/filamented_hold.lua"]={["Path"]="scripts/actions/spells/blue/filamented_hold.lua",["SHA256"]="8391b93592fbb0657a7dc68b58f00aa1fe334ea2d4385d06f96f16f905b65d10",["Text"]="-----------------------------------\n-- Spell: Filamented Hold\n-- Reduces the attack speed of enemies within a fan-shaped area originating from the caster\n-- Spell cost: 38 MP\n-- Monster Type: Vermin\n-- Spell Type: Magical (Earth)\n-- Blue Magic Points: 3\n-- Stat Bonus: VIT+1\n-- Level: 52\n-- Casting Time: 2 seconds\n-- Recast Time: 20 seconds\n-- Magic Bursts on: Scission, Gravitation, and Darkness\n-- Combos: Clear Mind\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params           = {}\n    params.ecosystem       = xi.ecosystem.VERMIN\n    params.effect          = xi.effect.SLOW\n    params.power           = 2500\n    params.tick            = 0\n    params.duration        = 90\n    params.resistThreshold = 0.5\n    params.isGaze          = false\n    params.isConal         = true\n\n    return xi.spells.blue.useEnfeeblingSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/firespit.lua"]={["Path"]="scripts/actions/spells/blue/firespit.lua",["SHA256"]="192bc0a28dc773859556a202a91aa375a1114ff272b5b7249855b44248e76389",["Text"]="-----------------------------------\n-- Spell: Firespit\n-- Deals fire damage to an enemy\n-- Spell cost: 121 MP\n-- Monster Type: Beastmen\n-- Spell Type: Magical (Fire)\n-- Blue Magic Points: 5\n-- Stat Bonus: STR+3\n-- Level: 68\n-- Casting Time: 6.5 seconds\n-- Recast Time: 42.75 seconds\n-- Magic Bursts on: Liquefaction, Fusion, and Light\n-- Combos: Conserve MP\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params      = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem  = xi.ecosystem.BEASTMEN\n    params.attackType = xi.attackType.MAGICAL\n    params.damageType = xi.damageType.FIRE\n    params.dStat      = xi.mod.INT\n\n    params.ftp0            = 3.0\n    params.dStatMultiplier = 1.5\n    params.baseDamageCap   = 69\n\n    params.int_wsc = 0.2\n    params.mnd_wsc = 0.2\n\n    return xi.spells.blue.useMagicalSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/flying_hip_press.lua"]={["Path"]="scripts/actions/spells/blue/flying_hip_press.lua",["SHA256"]="eb878b079f56bd29698eba3fccefe69bccde505358baf366f32977d040e28123",["Text"]="-----------------------------------\n-- Spell: Flying Hip Press\n-- Deals wind damage to enemies within range\n-- Spell cost: 125 MP\n-- Monster Type: Beastmen\n-- Spell Type: Magical (Wind)\n-- Blue Magic Points: 3\n-- Stat Bonus: AGI+1\n-- Level: 58\n-- Casting Time: 5.75 seconds\n-- Recast Time: 34.5 seconds\n-- Magic Bursts On: Detonation, Fragmentation, and Light\n-- Combos: Max HP Boost\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params      = {}\n    params.ecosystem  = xi.ecosystem.BEASTMEN\n    params.attackType = xi.attackType.BREATH\n    params.damageType = xi.damageType.WIND\n    params.hpMod      = 3\n    params.lvlMod     = 0\n\n    return xi.spells.blue.useBreathSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/foot_kick.lua"]={["Path"]="scripts/actions/spells/blue/foot_kick.lua",["SHA256"]="64e298adae45521bbafe34a88f0fdd69588c879966e1a1609d97231ccd9400a1",["Text"]="-----------------------------------\n-- Spell: Foot Kick\n-- Deals critical damage. Chance of critical hit varies with TP\n-- Spell cost: 5 MP\n-- Monster Type: Beasts\n-- Spell Type: Physical (Slashing)\n-- Blue Magic Points: 2\n-- Stat Bonus: AGI+1\n-- Level: 1\n-- Casting Time: 0.5 seconds\n-- Recast Time: 6.5 seconds\n-- Skillchain Property: Detonation\n-- Combos: Lizard Killer\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params      = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem  = xi.ecosystem.BEAST\n    params.tpModifier = xi.spells.blue.tpMod.CRITICAL\n\n    if params.hasAzureLore then\n        params.critChance = 35\n    elseif params.hasChainAffinity then\n        params.critChance = xi.spells.blue.calculatefTP(caster:getTP(), 0, 15, 30)\n    end\n\n    params.attackType     = xi.attackType.PHYSICAL\n    params.damageType     = xi.damageType.SLASHING\n    params.skillchainType = xi.skillchainType.DETONATION\n\n    params.numHits       = 1\n    params.ftp0          = 1.0\n    params.ftp1500       = 1.0\n    params.ftp3000       = 1.0\n    params.ftpAzure      = 1.0\n    params.baseDamageCap = 9\n    params.attackMult    = 2\n\n    params.str_wsc = 0.1\n    params.dex_wsc = 0.1\n\n    return xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/frenetic_rip.lua"]={["Path"]="scripts/actions/spells/blue/frenetic_rip.lua",["SHA256"]="6d2273c0db6989626b83421b0932a887285ea1772e6eb09389325d56a24c5752",["Text"]="-----------------------------------\n-- Spell: Frenetic Rip\n-- Delivers a threefold attack. Damage varies with TP\n-- Spell cost: 61 MP\n-- Monster Type: Demon\n-- Spell Type: Physical (Blunt)\n-- Blue Magic Points: 3\n-- Stat Bonus: INT+1\n-- Level: 63\n-- Casting Time: 0.5 seconds\n-- Recast Time: 28.5 seconds\n-- Skillchain Element: Induration\n-- Combos: Accuracy Bonus\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params          = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem      = xi.ecosystem.DEMON\n    params.tpModifier     = xi.spells.blue.tpMod.DAMAGE\n    params.attackType     = xi.attackType.PHYSICAL\n    params.damageType     = xi.damageType.HAND_TO_HAND\n    params.skillchainType = xi.skillchainType.INDURATION\n\n    params.numHits       = 3\n    params.ftp0          = 1.359375\n    params.ftp1500       = 2.0703125\n    params.ftp3000       = 2.359375\n    params.ftpAzure      = 2.609375\n    params.baseDamageCap = 73\n\n    params.str_wsc = 0.2\n    params.dex_wsc = 0.2\n\n    return xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/frightful_roar.lua"]={["Path"]="scripts/actions/spells/blue/frightful_roar.lua",["SHA256"]="c3848e7db2d98f690fcbbc217a58fe18461f7a96d903485cfa529ff816b1d07b",["Text"]="-----------------------------------\n-- Spell: Frightful Roar\n-- Weakens defense of enemies within range\n-- Spell cost: 32 MP\n-- Monster Type: Demon\n-- Spell Type: Magical (Wind)\n-- Blue Magic Points: 3\n-- Stat Bonus: AGI+2\n-- Level: 50\n-- Casting Time: 2 seconds\n-- Recast Time: 20 seconds\n-- Magic Bursts on: Detonation, Fragmentation, and Light\n-- Combos: Auto Refresh\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params           = {}\n    params.ecosystem       = xi.ecosystem.DEMON\n    params.effect          = xi.effect.DEFENSE_DOWN\n    params.power           = 10\n    params.tick            = 0\n    params.duration        = 180\n    params.resistThreshold = 0.5\n    params.isGaze          = false\n    params.isConal         = false\n\n    return xi.spells.blue.useEnfeeblingSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/frost_breath.lua"]={["Path"]="scripts/actions/spells/blue/frost_breath.lua",["SHA256"]="a02be8c25f1efc39c668a0106ae35f3c52c2ba72a2df8c7089b9556a510adacd",["Text"]="-----------------------------------\n-- Spell: Frost Breath\n-- Deals ice damage to enemies within a fan-shaped area originating from the caster. Additional effect: Paralysis\n-- Spell cost: 136 MP\n-- Monster Type: Lizards\n-- Spell Type: Magical (Ice)\n-- Blue Magic Points: 3\n-- Stat Bonus: INT-2\n-- Level: 66\n-- Casting Time: 6.5 seconds\n-- Recast Time: 42.75 seconds\n-- Magic Bursts on: Induration, Distortion, and Darkness\n-- Combos: Conserve MP\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params      = {}\n    params.ecosystem  = xi.ecosystem.LIZARD\n    params.attackType = xi.attackType.BREATH\n    params.damageType = xi.damageType.ICE\n    params.hpMod      = 3\n    params.lvlMod     = 0.625\n    params.isConal    = true\n\n    -- Handle damage.\n    local damage = xi.spells.blue.useBreathSpell(caster, target, spell, params)\n\n    if damage <= 0 then\n        return damage\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.PARALYSIS, 15, 0, 60 },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/frypan.lua"]={["Path"]="scripts/actions/spells/blue/frypan.lua",["SHA256"]="b3a26039e82ce71fcc843f57b7bc347c3dea75b1369a09df516c6385dd56eda5",["Text"]="-----------------------------------\n-- Spell: Frypan\n-- Delivers an area attack. Additional effect: \"Stun.\" Accuracy varies with TP\n-- Spell cost: 65 MP\n-- Monster Type: Beastmen\n-- Spell Type: Physical (Blunt)\n-- Blue Magic Points: 3\n-- Stat Bonus: DEX+2\n-- Level: 63\n-- Casting Time: 1 seconds\n-- Recast Time: 26 seconds\n-- Skillchain Element(s): Impcation\n-- Combos: Max HP Boost\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params      = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem  = xi.ecosystem.BEASTMEN\n    params.tpModifier = xi.spells.blue.tpMod.ACC\n\n    if params.hasAzureLore then\n        params.bonusAcc = 70\n    elseif params.hasChainAffinity then\n        params.bonusAcc = math.floor(caster:getTP() / 50)\n    end\n\n    params.attackType     = xi.attackType.PHYSICAL\n    params.damageType     = xi.damageType.BLUNT\n    params.skillchainType = xi.skillchainType.IMPACTION\n    params.shadowBehavior = xi.mobskills.shadowBehavior.NUMSHADOWS_3 -- guessed\n\n    params.numHits       = 1\n    params.ftp0          = 1.7734375\n    params.ftp1500       = 1.7734375\n    params.ftp3000       = 1.7734375\n    params.ftpAzure      = 1.7734375\n    params.baseDamageCap = 999 -- uncapped\n\n    params.str_wsc    = 0.2\n    params.mnd_wsc    = 0.2\n\n    -- Handle damage.\n    local damage = xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\n\n    if params.hitsLanded <= 0 then\n        return damage\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.STUN, 1, 0, 5 },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/geist_wall.lua"]={["Path"]="scripts/actions/spells/blue/geist_wall.lua",["SHA256"]="704cc8858a3d4caba242c7398c13f2914af2ba3f5fdfab41c5e93d1512595127",["Text"]="-----------------------------------\n-- Spell: Geist Wall\n-- Removes one beneficial magic effect from enemies within range\n-- Spell cost: 35 MP\n-- Monster Type: Lizards\n-- Spell Type: Magical (Dark)\n-- Blue Magic Points: 3\n-- Stat Bonus: HP-5, MP+10\n-- Level: 46\n-- Casting Time: 3 seconds\n-- Recast Time: 30 seconds\n-- Magic Bursts on: Compression, Gravitation, Darkness\n-- Combos: None\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local effect = xi.effect.NONE\n\n    local params =\n    {\n        effectId       = xi.effect.NONE,\n        magicalElement = spell:getElement(),\n        actorStat      = xi.mod.INT,\n        skillType      = xi.skill.BLUE_MAGIC,\n        spellGroup     = spell:getSpellGroup(),\n    }\n\n    local resist = xi.combat.magicHitRate.calculateResistRate(caster, target, params)\n\n    if resist >= 0.5 then\n        effect = target:dispelStatusEffect()\n        spell:setMsg(xi.msg.basic.MAGIC_ERASE)\n        if effect == xi.effect.NONE then\n            spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n        end\n    else\n        spell:setMsg(xi.msg.basic.MAGIC_RESIST)\n    end\n\n    return effect\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/goblin_rush.lua"]={["Path"]="scripts/actions/spells/blue/goblin_rush.lua",["SHA256"]="6b84338b8fd1ff28e6f9ba0a991b5d61cd7f79484df7e6a6ec9cdb80b4041636",["Text"]="-----------------------------------\n-- Spell: Goblin Rush\n-- Delivers a threefold attack. Accuracy varies with TP\n-- Spell cost: 81 MP\n-- Monster Type: BEASTMEN\n-- Spell Type: Physical (Blunt)\n-- Blue Magic Points: 3\n-- Stat Bonus: HP+10 DEX+3 MND-3\n-- Level: 81\n-- Casting Time: 0.5 seconds\n-- Recast Time: 25.5 seconds\n-- Skillchain Element(s): Fusion/Impaction\n-- Combos: Skillchain Bonus\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params      = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem  = xi.ecosystem.BEASTMEN\n    params.tpModifier = xi.spells.blue.tpMod.ACC\n\n    if params.hasAzureLore then\n        params.bonusAcc = 70\n    elseif params.hasChainAffinity then\n        params.bonusAcc = math.floor(caster:getTP() / 50)\n    end\n\n    params.attackType      = xi.attackType.PHYSICAL\n    params.damageType      = xi.damageType.BLUNT\n    params.skillchainType  = xi.skillchainType.FUSION\n    params.skillchainType2 = xi.skillchainType.IMPACTION\n\n    params.numHits       = 3\n    params.ftp0          = 1.25\n    params.ftp1500       = 1.25\n    params.ftp3000       = 1.25\n    params.ftpAzure      = 1.25\n    params.baseDamageCap = 75\n\n    params.str_wsc = 0.30\n    params.dex_wsc = 0.30\n\n    return xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/grand_slam.lua"]={["Path"]="scripts/actions/spells/blue/grand_slam.lua",["SHA256"]="67a46b253374b000c1622afbc3e165e43eeafcdb4abfe7ec6157bd979cb83de7",["Text"]="-----------------------------------\n-- Spell: Grand Slam\n-- Delivers an area attack. Damage varies with TP\n-- Spell cost: 24 MP\n-- Monster Type: Beastmen\n-- Spell Type: Physical (Blunt)\n-- Blue Magic Points: 2\n-- Stat Bonus: INT+1\n-- Level: 30\n-- Casting Time: 1 seconds\n-- Recast Time: 14.25 seconds\n-- Skillchain Element(s): Induration\n-- Combos: Defense Bonus\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params          = xi.spells.blue.getDefaultParams(caster)\n    params.tpModifier     = xi.spells.blue.tpMod.ATTACK\n    params.attackType     = xi.attackType.PHYSICAL\n    params.damageType     = xi.damageType.HAND_TO_HAND\n    params.skillchainType = xi.skillchainType.INDURATION\n    params.shadowBehavior = xi.mobskills.shadowBehavior.NUMSHADOWS_3 -- guessed\n\n    params.numHits       = 1\n    params.ftp0          = 1.0\n    params.ftp1500       = 1.0\n    params.ftp3000       = 1.0\n    params.ftpAzure      = 1.0\n    params.baseDamageCap = 33\n    params.attackMult    = 1.6\n\n    if params.hasAzureLore then\n        params.attackMult = 2.4\n    elseif params.hasChainAffinity then\n        params.attackMult = xi.spells.blue.calculatefTP(caster:getTP(), 1.6, 2, 2.3)\n    end\n\n    params.vit_wsc = 0.3\n\n    return xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/head_butt.lua"]={["Path"]="scripts/actions/spells/blue/head_butt.lua",["SHA256"]="1df9278f767c14ca93bf52324ac878c35022c8d223e441c8f2fef00a69b9c811",["Text"]="-----------------------------------\n-- Spell: Head Butt\n-- Damage varies with TP. Additional effect: \"Stun\"\n-- Spell cost: 12 MP\n-- Monster Type: Beastmen\n-- Spell Type: Physical (Blunt)\n-- Blue Magic Points: 3\n-- Stat Bonus: DEX+2\n-- Level: 12\n-- Casting Time: 0.5 seconds\n-- Recast Time: 10 seconds\n-- Skillchain Element(s): Impaction\n-- Combos: None\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params          = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem      = xi.ecosystem.BEASTMEN\n    params.tpModifier     = xi.spells.blue.tpMod.DAMAGE\n    params.attackType     = xi.attackType.PHYSICAL\n    params.damageType     = xi.damageType.BLUNT\n    params.skillchainType = xi.skillchainType.IMPACTION\n\n    params.numHits       = 1\n    params.ftp0          = 1.75\n    params.ftp1500       = 2.125\n    params.ftp3000       = 2.25\n    params.ftpAzure      = 2.375\n    params.baseDamageCap = 17\n    params.attackMult    = 1.05\n\n    params.str_wsc = 0.2\n    params.int_wsc = 0.2\n\n    -- Handle damage.\n    local damage = xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\n\n    if params.hitsLanded <= 0 then\n        return damage\n    end\n\n    -- Handle status effects.\n    -- Duration seems to be 2 - 8 seconds with float precision\n    local effectTable =\n    {\n        [1] = { xi.effect.STUN, 1, 0, math.randomFloat(2, 8) },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/healing_breeze.lua"]={["Path"]="scripts/actions/spells/blue/healing_breeze.lua",["SHA256"]="b1f2a7148993ad645766f81e3918c9ec74d37b8808ebd9533f60c054c3278f47",["Text"]="-----------------------------------\n-- Spell: Healing Breeze\n-- Restores HP for party members within area of effect\n-- Spell cost: 55 MP\n-- Monster Type: Beasts\n-- Spell Type: Magical (Wind)\n-- Blue Magic Points: 4\n-- Stat Bonus: CHR+2, HP+10\n-- Level: 16\n-- Casting Time: 4.5 seconds\n-- Recast Time: 15 seconds\n-----------------------------------\n-- Combos: Auto Regen\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params = {}\n\n    params.minCure         = 60\n    params.divisor0        = 0.6666\n    params.constant0       = -45\n    params.powerThreshold1 = 219\n    params.divisor1        = 2\n    params.constant1       = 65\n    params.powerThreshold2 = 459\n    params.divisor2        = 6.5\n    params.constant2       = 144.6666\n\n    return xi.spells.blue.useCuringSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/heat_breath.lua"]={["Path"]="scripts/actions/spells/blue/heat_breath.lua",["SHA256"]="c17b60bd18b6866c7a9fee59dfb9660cb08c0335ab2884f07e5a641b0b8c70b7",["Text"]="-----------------------------------\n-- Spell: Heat Breath\n-- Deals fire damage to enemies within a fan-shaped area originating from the caster\n-- Spell cost: 169 MP\n-- Monster Type: Beasts\n-- Spell Type: Magical (Fire)\n-- Blue Magic Points: 4\n-- Stat Bonus: STR+3\n-- Level: 71\n-- Casting Time: 7.5 seconds\n-- Recast Time: 49 seconds\n-- Magic Bursts on: Liquefaction, Fusion, Light\n-- Combos: Magic Attack Bonus\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params      = {}\n    params.ecosystem  = xi.ecosystem.BEAST\n    params.attackType = xi.attackType.BREATH\n    params.damageType = xi.damageType.FIRE\n    params.hpMod      = 2\n    params.lvlMod     = 0\n    params.isConal    = true\n\n    return xi.spells.blue.useBreathSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/heavy_strike.lua"]={["Path"]="scripts/actions/spells/blue/heavy_strike.lua",["SHA256"]="8898657890222c697b4efa5e32e0e49a0f0f251c6a64e35ae699d051958c41a9",["Text"]="-----------------------------------\n-- Spell: Heavy Strike\n-- Damage varies with TP\n-- Spell cost: 32 MP\n-- Monster Type: Arcana\n-- Spell Type: Physical (Blunt)\n-- Blue Magic Points: 3\n-- Stat Bonus: STR+2\n-- Level: 92\n-- Casting Time: 1 seconds\n-- Recast Time: 30 seconds\n-- Skillchain Element(s): Fragmentation, Transfixion\n-- Combos: Double Attack, Triple Attack\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\n-- Need to implement Automatic crit\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params           = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem       = xi.ecosystem.ARCANA\n    params.tpModifier      = xi.spells.blue.tpMod.ATTACK\n    params.attackType      = xi.attackType.PHYSICAL\n    params.damageType      = xi.damageType.HAND_TO_HAND\n    params.skillchainType  = xi.skillchainType.FRAGMENTATION\n    params.skillchainType2 = xi.skillchainType.TRANSFIXION\n\n    params.numHits       = 1\n    params.ftp0          = 2.5 -- Using https://wiki.ffo.jp/html/24367.html over bg-wiki for this\n    params.ftp1500       = 3.5\n    params.ftp3000       = 4.0\n    params.ftpAzure      = 4.0 -- This is a guess as blue gartr doesn't have this info\n    params.baseDamageCap = 75\n    params.bonusAcc      = -100\n    params.critChance    = 100 -- TODO: this should cap to 100%\n\n    params.str_wsc = 0.5\n\n    return xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/hecatomb_wave.lua"]={["Path"]="scripts/actions/spells/blue/hecatomb_wave.lua",["SHA256"]="0ecf6bdb52f151971b91424c45f85a553b768b5310842381b348430aad39cb86",["Text"]="-----------------------------------\n-- Spell: Hecatomb Wave\n-- Deals wind damage to enemies within a fan-shaped area originating from the caster. Additional effect: Blindness\n-- Spell cost: 116 MP\n-- Monster Type: Demons\n-- Spell Type: Magical (Wind)\n-- Blue Magic Points: 3\n-- Stat Bonus: AGI+1\n-- Level: 54\n-- Casting Time: 5.25 seconds\n-- Recast Time: 33.75 seconds\n-- Magic Bursts on: Detonation, Fragmentation, Light\n-- Combos: Max MP Boost\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params      = {}\n    params.ecosystem  = xi.ecosystem.DEMON\n    params.attackType = xi.attackType.BREATH\n    params.damageType = xi.damageType.WIND\n    params.hpMod      = 4\n    params.lvlMod     = 1.5\n    params.isConal    = true\n\n    -- Handle damage.\n    local damage = xi.spells.blue.useBreathSpell(caster, target, spell, params)\n\n    if damage <= 0 then\n        return damage\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.BLINDNESS, 20, 0, 60 },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/helldive.lua"]={["Path"]="scripts/actions/spells/blue/helldive.lua",["SHA256"]="d693b93854e70bbafacf575f13e17e597658d4c18d302162ef2c6d11b4a9f88d",["Text"]="-----------------------------------\n-- Spell: Helldive\n-- Damage varies with TP\n-- Spell cost: 16 MP\n-- Monster Type: Birds\n-- Spell Type: Physical (Blunt)\n-- Blue Magic Points: 2\n-- Stat Bonus: CHR+1, HP+5\n-- Level: 16\n-- Casting Time: 0.5 seconds\n-- Recast Time: 11.25 seconds\n-- Skillchain Property: Transfixion\n-- Combos: None\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params          = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem      = xi.ecosystem.BIRD\n    params.tpModifier     = xi.spells.blue.tpMod.DAMAGE\n    params.attackType     = xi.attackType.PHYSICAL\n    params.damageType     = xi.damageType.BLUNT\n    params.skillchainType = xi.skillchainType.TRANSFIXION\n\n    params.numHits       = 1\n    params.ftp0          = 1.25\n    params.ftp1500       = 1.625\n    params.ftp3000       = 2.00\n    params.ftpAzure      = 2.125\n    params.baseDamageCap = 19\n    params.attackMult    = 1.85\n\n    params.agi_wsc = 0.3\n\n    return xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/hydro_shot.lua"]={["Path"]="scripts/actions/spells/blue/hydro_shot.lua",["SHA256"]="cc663c7aae9ded118e86e4a9e748a240ff67621f61cef471aa4eabf1a7e69498",["Text"]="-----------------------------------\n-- Spell: Hydro Shot\n-- Additional effect: Enmity Down. Chance of effect varies with TP\n-- Spell cost: 55 MP\n-- Monster Type: Beastmen\n-- Spell Type: Physical (Blunt)\n-- Blue Magic Points: 3\n-- Stat Bonus: MND+2\n-- Level: 63\n-- Casting Time: 0.5 seconds\n-- Recast Time: 26 seconds\n-- Skillchain Element(s): Reverberation\n-- Combos: Rapid Shot\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params          = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem      = xi.ecosystem.BEASTMEN\n    params.tpModifier     = xi.spells.blue.tpMod.EFFECT_CHANCE\n    params.attackType     = xi.attackType.PHYSICAL\n    params.damageType     = xi.damageType.HAND_TO_HAND\n    params.skillchainType = xi.skillchainType.REVERBERATION\n\n    params.numHits       = 1\n    params.ftp0          = 1.25\n    params.ftp1500       = 1.25\n    params.ftp3000       = 1.25\n    params.ftpAzure      = 1.25\n    params.baseDamageCap = 999 -- uncapped\n    params.attackMult    = 1.85\n\n    params.agi_wsc = 0.3\n\n    -- Enmity Down amount is trivial, not worth implementing\n    -- Sources: https://www.applySpellDamagethreads/37619-Blue-Mage-Best-thread-ever?p=4845494&viewfull=1#post4845494 and https://www.bg-wiki.com/ffxi/Hydro_Shot\n\n    return xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/hysteric_barrage.lua"]={["Path"]="scripts/actions/spells/blue/hysteric_barrage.lua",["SHA256"]="27c829c106f3a2b484648b9aadf31940c9c43f8f1112888718040edc093b576c",["Text"]="-----------------------------------\n-- Spell: Hysteric Barrage\n-- Delivers a fivefold attack. Damage varies with TP\n-- Spell cost: 61 MP\n-- Monster Type: Beastmen\n-- Spell Type: Physical (Hand-to-Hand)\n-- Blue Magic Points: 5\n-- Stat Bonus: DEX+2, AGI+1\n-- Level: 69\n-- Casting Time: 0.5 seconds\n-- Recast Time: 28.5 seconds\n-- Skillchain Element: Detonation\n-- Combos: Evasion Bonus\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params          = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem      = xi.ecosystem.BEASTMEN\n    params.tpModifier     = xi.spells.blue.tpMod.DAMAGE\n    params.attackType     = xi.attackType.PHYSICAL\n    params.damageType     = xi.damageType.HAND_TO_HAND\n    params.skillchainType = xi.skillchainType.DETONATION\n\n    params.numHits       = 5\n    params.ftp0          = 1.25\n    params.ftp1500       = 1.625\n    params.ftp3000       = 1.75\n    params.ftpAzure      = 1.875\n    params.baseDamageCap = 80\n\n    params.dex_wsc = 0.3\n\n    return xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/ice_break.lua"]={["Path"]="scripts/actions/spells/blue/ice_break.lua",["SHA256"]="68a43892be5c0efadc7257e12bc257dcc80cb841bcb9d1e493584d29064973fd",["Text"]="-----------------------------------\n-- Spell: Ice Break\n-- Deals ice damage to enemies within range. Additional Effect: \"Bind\"\n-- Spell cost: 142 MP\n-- Monster Type: Arcana\n-- Spell Type: Magical (Ice)\n-- Blue Magic Points: 3\n-- Stat Bonus: INT+1\n-- Level: 50\n-- Casting Time: 5.25 seconds\n-- Recast Time: 33.75 seconds\n-- Magic Bursts on: Induration, Distortion, and Darkness\n-- Combos: Magic Defense Bonus\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params       = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem   = xi.ecosystem.ARCANA\n    params.attackType  = xi.attackType.MAGICAL\n    params.damageType  = xi.damageType.ICE\n    params.dStat       = xi.mod.INT\n\n    params.ftp0            = 2.25\n    params.dStatMultiplier = 1.0\n    params.baseDamageCap   = 69\n\n    params.int_wsc = 0.3\n\n    -- Handle damage.\n    local damage = xi.spells.blue.useMagicalSpell(caster, target, spell, params)\n\n    if damage <= 0 then\n        return damage\n    end\n\n    -- Handle status effects.\n    local effectTable =\n    {\n        [1] = { xi.effect.BIND, 1, 0, 30 },\n    }\n\n    xi.spells.blue.applyBlueAdditionalEffect(caster, target, params, effectTable)\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/infrasonics.lua"]={["Path"]="scripts/actions/spells/blue/infrasonics.lua",["SHA256"]="970cfa9b630797862eb455c14973e52613899a1c2bc7a1cbc7f863869d04d16e",["Text"]="-----------------------------------\n-- Spell: Infrasonics\n-- Lowers the evasion of enemies within a fan-shaped area originating from the caster\n-- Spell cost: 42 MP\n-- Monster Type: Lizards\n-- Spell Type: Magical (Ice)\n-- Blue Magic Points: 4\n-- Stat Bonus: INT+1\n-- Level: 65\n-- Casting Time: 5 seconds\n-- Recast Time: 120 seconds\n-- Magic Bursts on: Induration, Distortion, Darkness\n-- Combos: None\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params           = {}\n    params.ecosystem       = xi.ecosystem.LIZARD\n    params.effect          = xi.effect.EVASION_DOWN\n    params.power           = 20\n    params.tick            = 0\n    params.duration        = 60\n    params.resistThreshold = 0.5\n    params.isGaze          = false\n    params.isConal         = true\n\n    return xi.spells.blue.useEnfeeblingSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/jet_stream.lua"]={["Path"]="scripts/actions/spells/blue/jet_stream.lua",["SHA256"]="dbd58da4dea717e84677c50e55dba64bf854dd978898d58aac06a31aa886d9ad",["Text"]="-----------------------------------\n-- Spell: Jet Stream\n-- Delivers a threefold attack. Accuracy varies with TP\n-- Spell cost: 47 MP\n-- Monster Type: Birds\n-- Spell Type: Physical (Blunt)\n-- Blue Magic Points: 4\n-- Stat Bonus: DEX+2\n-- Level: 38\n-- Casting Time: 0.5 seconds\n-- Recast Time: 23 seconds\n-- Skillchain Element(s): Impaction\n-- Combos: Rapid Shot\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params      = xi.spells.blue.getDefaultParams(caster)\n    params.ecosystem  = xi.ecosystem.BIRD\n    params.tpModifier = xi.spells.blue.tpMod.ACC\n\n    -- TODO: this is made up\n    if params.hasAzureLore then\n        params.bonusAcc = 70\n    elseif params.hasChainAffinity then\n        params.bonusAcc = math.floor(caster:getTP() / 50)\n    end\n\n    params.attackType     = xi.attackType.PHYSICAL\n    params.damageType     = xi.damageType.BLUNT\n    params.skillchainType = xi.skillchainType.IMPACTION\n\n    params.numHits       = 3\n    params.ftp0          = 1.125\n    params.ftp1500       = 1.125\n    params.ftp3000       = 1.125\n    params.ftpAzure      = 1.125\n    params.baseDamageCap = 39\n    params.attackMult    = 1.3\n\n    params.agi_wsc = 0.3\n\n    return xi.spells.blue.usePhysicalSpell(caster, target, spell, params, action)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/jettatura.lua"]={["Path"]="scripts/actions/spells/blue/jettatura.lua",["SHA256"]="05023e3a547e75a87e592122a1a5564de3bcd11587ddb31c13c05268eaec0912",["Text"]="-----------------------------------\n-- Spell: Jettatura\n-- Enemies within a fan-shaped area originating from the caster are frozen with fear\n-- Spell cost: 37 MP\n-- Monster Type: Birds\n-- Spell Type: Magical (Dark)\n-- Blue Magic Points: 4\n-- Stat Bonus: MP+15\n-- Level: 48\n-- Casting Time: 0.5 seconds\n-- Recast Time: 2:00\n-- Magic Bursts on: Compression, Gravitation, Darkness\n-- Combos: None\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local params           = {}\n    params.ecosystem       = xi.ecosystem.BIRD\n    params.effect          = xi.effect.TERROR\n    params.power           = 1\n    params.tick            = 0\n    params.duration        = 5\n    params.resistThreshold = 0.5\n    params.isGaze          = true\n    params.isConal         = true\n\n    return xi.spells.blue.useEnfeeblingSpell(caster, target, spell, params)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/blue/light_of_penance.lua"]={["Path"]="scripts/actions/spells/blue/light_of_penance.lua",["SHA256"]="29059ae3589016b202315398b2059551d62111c1b474a638bdadb8a1cc6898ce",["Text"]="-----------------------------------\n-- Spell: Light of Penance\n-- Reduces an enemy's TP. Additional effect: Blindness and \"Bind\"\n-- Spell cost: 53 MP\n-- Monster Type: Beastmen\n-- Spell Type: Magical (Light)\n-- Blue Magic Points: 5\n-- Stat Bonus: CHR+1, HP+15\n-- Level: 58\n-- Casting Time: 3 seconds\n-- Recast Time: 60 seconds\n-- Magic Bursts on: Transfixion, Fusion, and Light\n-- Combos: Auto Refresh\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell, action)\n    local duration     = 30\n    local returnEffect = xi.effect.BLINDNESS\n\n    local params =\n    {\n        effectId       = xi.effect.BLINDNESS,\n        magicalElement = spell:getElement(),\n        actorStat      = xi.mod.INT,\n        skillType      = xi.skill.BLUE_MAGIC,\n        spellGroup     = spell:getSpellGroup(),\n    }\n\n    local resist = xi.combat.magicHitRate.calculateResistRate(caster, target, params)\n\n    if resist >= 0.5 then\n\n        spell:setMsg(xi.msg.basic.MAGIC_TP_REDUCE) -- this doesn't seem to do much\n        target:delTP(100)\n        local actionOne = target:addStatusEffect(xi.effect.BLINDNESS, { power = 10, duration = duration * resist, origin = caster })\n        local actionTwo = target:addStatusEffect(xi.effect.BIND, { power = 1, duration = duration * resist, origin = caster })\n\n        -- Gaze move\n        if target:isFacing(caster) and caster:isFacing(target) then\n\n            -- If at least one of effects got applied, set the message type\n            if actionOne or actionTwo then\n                spell:setMsg(xi.msg.basic.MAGIC_ENFEEB_IS)\n            end\n\n            -- Set the returnEffect to effectTwo if the first one failed\n            if not actionOne and actionTwo then\n                returnEffect = xi.effect.BIND\n            end\n\n        else\n            spell:setMsg(xi.msg.basic.MAGIC_NO_EFFECT)\n        end\n    else\n        spell:setMsg(xi.msg.basic.MAGIC_RESIST)\n    end\n\n    return returnEffect\nend\n\nreturn spellObject\n"}};
